"""
This module provides classes that manage (setup / teardown) remote processes
and services.

This module assumes that it sends commands to Linux OS with SSH and systemd.

Classes:
- :class:`SSHMixin`: Common methods used by other classes in this module.
- :class:`RemoteService`: Manages remote systemd unit via systemctl.
- :class:`RemoteProcess`: Manages remote process which forks upon running.
"""
import os
from functools import partial
from . import logger


class SSHMixin(object):
    """ Mixin class that provides methods used by classes below. """
    def __init__(self, ssh_connection):
        self._ssh = ssh_connection
        self._process = None

    def _send_command(self, command, wait=True):
        self._process = self._ssh.send_command(command)
        if wait:
            self._process.join()

    def _gather_output(self):
        exit_code = self._process.get_exit_code()
        output = self._process.read_output()
        error = self._process.read_error()

        self._log_output(exit_code, output, error)
        return exit_code, output, error

    def _log_output(self, exit_code, output, error):
        self.logger.debug("Exit code: {}.".format(exit_code))
        if output:
            self.logger.debug("Output (stdout):")
            self.logger.debug(output)
        if error:
            self.logger.debug("Error output (stderr):")
            self.logger.debug(error)


class PIDFinder(object):
    def __init__(self, ssh_connection, port):
        self._ssh = ssh_connection
        self._port = port

    def find_pids_by_port(self):
        """
        There is a possibility that multiple programs are listening on one port,
        where each program listens on different network interface. This method
        lists process id (PID) for all of this programs excluding the Python process.
        :return: List with process IDs (PIDs) of programs, that listens on
            given port excluding the Python process.
        """
        pids = self._ssh.execute('lsof -t -i :{}'.format(self._port)).splitlines()
        python_pid = os.getpid()
        pids = [int(pid) for pid in pids if len(pid) != 0 and int(pid) != python_pid]
        return pids


class RemoteService(SSHMixin):
    """
    This class is a wrapper around taf.transport.ssh - it makes it easier to
    manage remote systemd units.
    """
    IS_ACTIVE_CMD = 'systemctl is-active {service}'
    START_CMD = 'systemctl start {service}'
    STOP_CMD = 'systemctl stop {service}'
    RESTART_CMD = 'systemctl restart {service}'

    # TODO: Add method docstrings.
    # TODO: Update class docstring to include method / fields index.
    # TODO: Unit tests.

    def __init__(self, ssh_connection, service_name):
        super(RemoteService, self).__init__(ssh_connection)
        self.logger = logger.getChild(self.__class__.__name__)
        self.restart = partial(self._send_systemctl_cmd, "Restarting",
                               self.RESTART_CMD)
        self.start = partial(self._send_systemctl_cmd, "Starting",
                             self.START_CMD)
        self.stop = partial(self._send_systemctl_cmd, "Stopping",
                            self.STOP_CMD)

        self.service_name = service_name

    def is_active(self):
        """
        check if the server is active
        active - True
        inactive - False
        :return: bool of state
        """
        logged_action = "Checking the state of"
        exit_code, state, _ = self._send_systemctl_cmd(logged_action,
                                                       self.IS_ACTIVE_CMD)
        is_active = (exit_code == 0)
        self._log_state(state)
        return is_active

    def _log_state(self, state):
        state = state.strip()
        log_msg = "Service {service} is in state \"{state}\"."
        log_msg = log_msg.format(service=self.service_name, state=state)
        self.logger.info(log_msg)

    def _send_systemctl_cmd(self, logged_action, command_template):
        """
        send command in ssh connect and log the action.
        :param logged_action: string type of action's name
        :param command_template: command gonna be send
        :return: execute result, output and error information
        """
        self._log_action(logged_action)

        systemctl_command = self._generate_systemctl_command(command_template)
        self._send_command(systemctl_command)
        systemctl_exit_code, output, error = self._gather_output()

        return systemctl_exit_code, output, error

    def _log_action(self, logged_action):
        """
        log action into robot log file.
        """
        log_msg = "{action} {service} service."
        log_msg = log_msg.format(action=logged_action,
                                 service=self.service_name)
        self.logger.info(log_msg)

    def _generate_systemctl_command(self, command_template):
        return command_template.format(service=self.service_name)


class RemoteProcess(SSHMixin):
    """
    a class to manage server process like egate and edaemon.
    content functions to generate commands.
    """
    CD_CMD_TEMPLATE = 'cd {path}; {command}'
    PKILL_CMD_TEMPLATE = 'pkill -9 -f "{command}"'
    SUDO_CMD_TEMPLATE_WITH_PD = 'echo {password} | sudo -S {command}'
    SUDO_CMD_TEMPLATE = 'sudo {command}'

    def __init__(self, ssh_connection, command, cd_path=None, sudo=False,
                 password=None, port=None, nostats=False):
        super(RemoteProcess, self).__init__(ssh_connection)
        self.logger = logger.getChild(self.__class__.__name__)

        self._sudo = sudo
        self._cd_path = cd_path
        self._command = command
        self._password = password
        self._last_stderr = None
        self._last_stdout = None
        self._port = port
        self._nostats = nostats
        self._pid_finder = PIDFinder(ssh_connection, port)

    # TODO: Add class docstring.
    # TODO: Add method docstrings.
    # TODO: Add unit tests.

    def start(self, wait=True):
        self._log_action("Starting")
        if self._cd_path:
            self._log_directory_change()

        start_command = self._generate_start_command()
        self._send_command(start_command, wait=wait)
        self._last_stdout = self._process.stdout
        self._last_stderr = self._process.stderr
        if wait:
            return self._gather_output()
        else:
            return 0, None, None

    def read_output(self):
        return self._read_channelfile(self._last_stdout)

    def read_error(self):
        return self._read_channelfile(self._last_stderr)

    @staticmethod
    def _read_channelfile(channelfile):
        if channelfile is None:
            return None
        return channelfile.read().decode(errors='ignore')

    def kill(self):
        self._log_action("Running pkill on")

        kill_command = self._generate_kill_command()
        self._send_command(kill_command)
        return self._gather_output()

    def kill_processes_that_occupies_given_port(self):
        list_of_pids = self._pid_finder.find_pids_by_port()
        if len(list_of_pids) == 0:
            msg = 'No process is using port {}. ' \
                  'No need for running kill command.'
            return logger.info(msg.format(self._port))
        elif len(list_of_pids) == 1:
            self._kill_process_by_pid(list_of_pids[0])
        else:
            self._kill_multiple_processes_by_pids(list_of_pids)

    def _kill_multiple_processes_by_pids(self, list_of_pids):
        for pid in list_of_pids:
            self._kill_process_by_pid(pid)

    def _kill_process_by_pid(self, pid):
        process_name = self._ssh.execute(
            'ps -p {} -o comm='.format(pid)).strip()
        logger.info('Killing {} process'.format(process_name))
        self._send_command('kill -9 {}'.format(pid))

    def _log_action(self, action):
        log_msg = "{action} process \"{process}\"."
        log_msg = log_msg.format(action=action, process=self._command)
        self.logger.info(log_msg)

    def _log_directory_change(self):
        log_msg = "The process will be started from directory \"{path}\"."
        log_msg = log_msg.format(path=self._cd_path)
        self.logger.info(log_msg)

    def _generate_start_command(self):
        command = self._command
        command = self._add_sudo_if_needed(command=command,
                                           password=self._password)
        command = self._add_cd_if_needed(command)
        command = self._add_nostats_if_needed(command)
        return command

    def _generate_kill_command(self):
        command = self._command
        command = self.PKILL_CMD_TEMPLATE.format(command=command)
        command = self._add_sudo_if_needed(command=command,
                                           password=self._password)
        return command

    def _add_sudo_if_needed(self, command, password):
        if self._sudo:
            if password is None:
                return self.SUDO_CMD_TEMPLATE.format(command=command)
            else:
                return self.SUDO_CMD_TEMPLATE_WITH_PD.format(command=command,
                                                             password=password)
        return command

    def _add_cd_if_needed(self, command):
        if self._cd_path:
            return self.CD_CMD_TEMPLATE.format(path=self._cd_path,
                                               command=command)
        return command
    
    def _add_nostats_if_needed(self, command):
        if self._nostats:
            command = "{} --nostats".format(command)
        return command
